      ).toThrow(RangeError);
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 500 }],
            5.5,
          ),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 500 }],
            -1,
          ),
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    const brackets = [
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
      { upToGrams: 5000, costCents: 1200 },
    ];

    it("returns 0 for empty cart", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      expect(calc.computeShippingCents([], 1000)).toBe(0);
    });

    it("returns 0 when total weight is 0 (no weightGrams)", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      expect(calc.computeShippingCents([makeLine("a", undefined, 2)], 1000)).toBe(0);
    });

    it("selects first bracket when weight is within it", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      expect(calc.computeShippingCents([makeLine("a", 250, 1)], 1000)).toBe(300);
    });

    it("selects bracket at boundary (weight == upToGrams)", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      expect(calc.computeShippingCents([makeLine("a", 500, 1)], 1000)).toBe(300);
    });

    it("selects next bracket when weight exceeds previous boundary", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      expect(calc.computeShippingCents([makeLine("a", 501, 1)], 1000)).toBe(600);
    });

    it("selects highest bracket at its boundary", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      expect(calc.computeShippingCents([makeLine("a", 5000, 1)], 1000)).toBe(1200);
    });

    it("uses overflow cost when weight exceeds all brackets", () => {
      const calc = new WeightBasedShippingCalculator(brackets, 2000);
      expect(calc.computeShippingCents([makeLine("a", 5001, 1)], 1000)).toBe(2000);
    });

    it("falls back to heaviest bracket cost when no overflow specified", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      expect(calc.computeShippingCents([makeLine("a", 10000, 1)], 1000)).toBe(1200);
    });

    it("sums weight across multiple lines", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // 300 * 2 = 600g → second bracket
      const lines = [makeLine("a", 300, 2)];
      expect(calc.computeShippingCents(lines, 1000)).toBe(600);
    });

    it("sorts brackets regardless of input order", () => {
      const unordered = [
        { upToGrams: 5000, costCents: 1200 },
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 1000, costCents: 600 },
      ];
      const calc = new WeightBasedShippingCalculator(unordered);
      expect(calc.computeShippingCents([makeLine("a", 400, 1)], 1000)).toBe(300);
    });
  });
});

import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import type { Product } from "../src/product.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";

const productA: Product = { id: "a", name: "Widget", unitPriceCents: 1000 };
const productB: Product = { id: "b", name: "Gadget", unitPriceCents: 2000, weightGrams: 500 };

describe("Cart - line management", () => {
  it("add increases item count", () => {
    const cart = new Cart();
    cart.add(productA, 2);
    expect(cart.itemCount).toBe(2);
  });

  it("add merges quantity for same product", () => {
    const cart = new Cart();
    cart.add(productA, 2);
    cart.add(productA, 3);
    expect(cart.itemCount).toBe(5);
  });

  it("add throws for non-positive quantity", () => {
    const cart = new Cart();
    expect(() => cart.add(productA, 0)).toThrow(RangeError);
    expect(() => cart.add(productA, -1)).toThrow(RangeError);
    expect(() => cart.add(productA, 1.5)).toThrow(RangeError);
  });

  it("add throws for negative unitPriceCents", () => {
    const cart = new Cart();
    const bad: Product = { id: "bad", name: "Bad", unitPriceCents: -1 };
    expect(() => cart.add(bad, 1)).toThrow(RangeError);
  });

  it("remove returns true for existing product", () => {
    const cart = new Cart();
    cart.add(productA, 1);
    expect(cart.remove("a")).toBe(true);
    expect(cart.itemCount).toBe(0);
  });

  it("remove returns false for unknown product", () => {
    const cart = new Cart();
    expect(cart.remove("nonexistent")).toBe(false);
  });

  it("updateQuantity changes quantity", () => {
    const cart = new Cart();
    cart.add(productA, 5);
    cart.updateQuantity("a", 2);
    expect(cart.itemCount).toBe(2);
  });

  it("updateQuantity with 0 removes the line", () => {
    const cart = new Cart();
    cart.add(productA, 3);
    cart.updateQuantity("a", 0);
    expect(cart.itemCount).toBe(0);
  });

  it("updateQuantity throws for unknown product", () => {
    const cart = new Cart();
    expect(() => cart.updateQuantity("x", 1)).toThrow("Product x is not in the cart");
  });

  it("updateQuantity throws for negative quantity", () => {
    const cart = new Cart();
    cart.add(productA, 1);
    expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
  });

  it("clear empties the cart", () => {
    const cart = new Cart();
    cart.add(productA, 2);
    cart.add(productB, 3);
    cart.clear();
    expect(cart.itemCount).toBe(0);
  });

  it("snapshot returns deep copy", () => {
    const cart = new Cart();
    cart.add(productA, 1);
    const snap = cart.snapshot();
    (snap as any)[0].quantity = 999;
    expect(cart.itemCount).toBe(1);
  });
});

describe("Cart - pricing pipeline", () => {
  it("computes subtotal as sum of unitPriceCents * quantity", () => {
    const cart = new Cart();
    cart.add(productA, 2); // 2000
    cart.add(productB, 1); // 2000
    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(4000);
  });

  it("applies discount then tax on discounted subtotal", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(500),
    };
    const taxCalculator: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(175),
    };
    const cart = new Cart({ discountPolicy, taxCalculator });
    cart.add(productA, 2); // subtotal 2000
    const totals = cart.totals();

    expect(totals.subtotalCents).toBe(2000);
    expect(totals.discountCents).toBe(500);
    expect(discountPolicy.computeDiscountCents).toHaveBeenCalledWith(2000);
    // Tax computed on discounted subtotal: 2000 - 500 = 1500
    expect(taxCalculator.computeTaxCents).toHaveBeenCalledWith(1500, "US");
    expect(totals.taxCents).toBe(175);
  });

  it("shipping receives discounted subtotal", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(200),
    };
    const shippingCalculator: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(599),
    };
    const cart = new Cart({ discountPolicy, shippingCalculator });
    cart.add(productA, 1); // subtotal 1000
    const totals = cart.totals();

    expect(shippingCalculator.computeShippingCents).toHaveBeenCalledWith(
      expect.any(Array),
      800, // 1000 - 200
    );
    expect(totals.shippingCents).toBe(599);
  });

  it("totalCents = discountedSubtotal + tax + shipping", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: () => 100,
    };
    const taxCalculator: TaxCalculator = {
      computeTaxCents: () => 50,
    };
    const shippingCalculator: ShippingCalculator = {
      computeShippingCents: () => 300,
    };
    const cart = new Cart({ discountPolicy, taxCalculator, shippingCalculator });
    cart.add(productA, 1); // subtotal 1000
    const totals = cart.totals();

    // discountedSubtotal = 1000 - 100 = 900; total = 900 + 50 + 300 = 1250
    expect(totals.totalCents).toBe(1250);
  });

  it("clamps discount to [0, subtotal]", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: () => 9999, // over subtotal
    };
    const cart = new Cart({ discountPolicy });
    cart.add(productA, 1); // subtotal 1000
    const totals = cart.totals();
    expect(totals.discountCents).toBe(1000); // clamped to subtotal
    expect(totals.totalCents).toBe(0); // no tax, no shipping by default
  });

  it("clamps negative discount to 0", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: () => -500,
    };
    const cart = new Cart({ discountPolicy });
    cart.add(productA, 1);
    const totals = cart.totals();
    expect(totals.discountCents).toBe(0);
  });

  it("clamps negative tax to 0", () => {
    const taxCalculator: TaxCalculator = {
      computeTaxCents: () => -100,
    };
    const cart = new Cart({ taxCalculator });
    cart.add(productA, 1);
    expect(cart.totals().taxCents).toBe(0);
  });

  it("clamps negative shipping to 0", () => {
    const shippingCalculator: ShippingCalculator = {
      computeShippingCents: () => -50,
    };
    const cart = new Cart({ shippingCalculator });
    cart.add(productA, 1);
    expect(cart.totals().shippingCents).toBe(0);
  });

  it("empty cart totals are all zero", () => {
    const cart = new Cart();
    const totals = cart.totals();
    expect(totals).toEqual({
      subtotalCents: 0,
      discountCents: 0,
      taxCents: 0,
      shippingCents: 0,
      totalCents: 0,
    });
  });

  it("uses custom region for tax", () => {
    const taxCalculator: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(0),
    };
    const cart = new Cart({ taxCalculator, region: "FR" });
    cart.add(productA, 1);
    cart.totals();
    expect(taxCalculator.computeTaxCents).toHaveBeenCalledWith(1000, "FR");
  });
});

