import { InventoryError, refreshPrices } from "../src/inventory.ts";
import type { PriceFetcher, InventoryChecker } from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";
import type { Product, CartLine } from "../src/product.ts";
import { PercentageDiscountPolicy } from "../src/pricing.ts";
import { FlatShippingCalculator } from "../src/shipping.ts";

const productA: Product = { id: "a", name: "Widget", unitPriceCents: 1000 };
const productB: Product = { id: "b", name: "Gadget", unitPriceCents: 2000 };

describe("refreshPrices", () => {
  it("updates line prices from fetcher", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn()
        .mockResolvedValueOnce(1100)
        .mockResolvedValueOnce(2200),
    };
    const lines: CartLine[] = [
      { product: productA, quantity: 2 },
      { product: productB, quantity: 1 },
    ];
    const result = await refreshPrices(lines, fetcher);
    expect(result[0].product.unitPriceCents).toBe(1100);
    expect(result[1].product.unitPriceCents).toBe(2200);
    expect(result[0].quantity).toBe(2);
  });

  it("throws RangeError for invalid fetched price", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(-1),
    };
    const lines: CartLine[] = [{ product: productA, quantity: 1 }];
    await expect(refreshPrices(lines, fetcher)).rejects.toThrow(RangeError);
  });

  it("throws RangeError for non-integer fetched price", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(10.5),
    };
    const lines: CartLine[] = [{ product: productA, quantity: 1 }];
    await expect(refreshPrices(lines, fetcher)).rejects.toThrow(RangeError);
  });

  it("propagates fetcher rejection", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("network")),
    };
    const lines: CartLine[] = [{ product: productA, quantity: 1 }];
    await expect(refreshPrices(lines, fetcher)).rejects.toThrow("network");
  });
});

describe("Cart.checkout()", () => {
  it("refreshes prices before computing totals", async () => {
    const cart = new Cart();
    cart.add(productA, 1);

    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(1500),
    };

    const result = await cart.checkout({ priceFetcher });
    expect(result.lines[0].product.unitPriceCents).toBe(1500);
    expect(result.totals.subtotalCents).toBe(1500);
  });

  it("works without any collaborators", async () => {
    const cart = new Cart();
    cart.add(productA, 2);
    const result = await cart.checkout();
    expect(result.totals.subtotalCents).toBe(2000);
  });

  it("throws InventoryError when item is unavailable", async () => {
    const cart = new Cart();
    cart.add(productA, 5);

    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: false, reason: "out of stock" }),
    };

    try {
      await cart.checkout({ inventoryChecker });
      expect.fail("should have thrown");
    } catch (e) {
      expect(e).toBeInstanceOf(InventoryError);
      const err = e as InventoryError;
      expect(err.productId).toBe("a");
      expect(err.requested).toBe(5);
      expect(err.message).toBe("out of stock");
    }
  });

  it("throws InventoryError on partial-stock denial", async () => {
    const cart = new Cart();
    cart.add(productA, 10);

    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 3,
      }),
    };

    try {
      await cart.checkout({ inventoryChecker });
      expect.fail("should have thrown");
    } catch (e) {
      expect(e).toBeInstanceOf(InventoryError);
      const err = e as InventoryError;
      expect(err.productId).toBe("a");
      expect(err.requested).toBe(10);
      expect(err.available).toBe(3);
    }
  });

  it("passes when inventory is available", async () => {
    const cart = new Cart();
    cart.add(productA, 2);

    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true }),
    };

    const result = await cart.checkout({ inventoryChecker });
    expect(result.totals.subtotalCents).toBe(2000);
  });

  it("uses asyncTaxProvider when supplied", async () => {
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.10),
    };
    const cart = new Cart({ region: "US-CA" });
    cart.add(productA, 1); // subtotal 1000, no discount → tax 10% of 1000 = 100

    const result = await cart.checkout({ asyncTaxProvider });
    expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US-CA");
    expect(result.totals.taxCents).toBe(100);
  });

  it("async tax uses discounted subtotal", async () => {
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.10),
    };
    const discountPolicy = new PercentageDiscountPolicy(20);
    const cart = new Cart({ discountPolicy, region: "US" });
    cart.add(productA, 1); // subtotal 1000, 20% discount = 200, taxable = 800

    const result = await cart.checkout({ asyncTaxProvider });
    expect(result.totals.discountCents).toBe(200);
    expect(result.totals.taxCents).toBe(80); // 10% of 800
  });

  it("combines price refresh, inventory, async tax, discount, and shipping", async () => {
    const discountPolicy = new PercentageDiscountPolicy(10);
    const shippingCalculator = new FlatShippingCalculator(500);
    const cart = new Cart({ discountPolicy, shippingCalculator, region: "US" });
    cart.add(productA, 2); // will be repriced

    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(1200),
    };
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 100 }),
    };
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.08),
    };

    const result = await cart.checkout({ priceFetcher, inventoryChecker, asyncTaxProvider });

    // subtotal: 1200 * 2 = 2400
    expect(result.totals.subtotalCents).toBe(2400);
    // discount: 10% of 2400 = 240
    expect(result.totals.discountCents).toBe(240);
    // taxable: 2400 - 240 = 2160, tax 8% = 172.8 → 172
    expect(result.totals.taxCents).toBe(172);
    // shipping: flat 500
    expect(result.totals.shippingCents).toBe(500);
    // total: 2160 + 172 + 500 = 2832
    expect(result.totals.totalCents).toBe(2832);
  });

  it("propagates asyncTaxProvider rejection", async () => {
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
    };
    const cart = new Cart();
    cart.add(productA, 1);
    await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow("tax service down");
  });

  it("first failing inventory item wins", async () => {
    const cart = new Cart();
    cart.add(productA, 1);
    cart.add(productB, 1);

    const inventoryChecker: InventoryChecker = {
      check: vi.fn()
        .mockResolvedValueOnce({ available: true })
        .mockResolvedValueOnce({ available: false, reason: "discontinued" }),
    };

    try {
      await cart.checkout({ inventoryChecker });
      expect.fail("should have thrown");
    } catch (e) {
      expect(e).toBeInstanceOf(InventoryError);
      expect((e as InventoryError).productId).toBe("b");
    }
  });
});

describe("InventoryError", () => {
  it("has correct shape", () => {
    const err = new InventoryError("msg", "prod-1", 5, 2);
    expect(err.name).toBe("InventoryError");
    expect(err.message).toBe("msg");
    expect(err.productId).toBe("prod-1");
    expect(err.requested).toBe(5);
    expect(err.available).toBe(2);
    expect(err).toBeInstanceOf(Error);
  });

  it("available can be undefined", () => {
    const err = new InventoryError("gone", "prod-2", 3, undefined);
    expect(err.available).toBeUndefined();
  });
});

import { describe, it, expect } from "vitest";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
  CompositeDiscountPolicy,
} from "../src/pricing.ts";

describe("NoDiscountPolicy", () => {
  const policy = new NoDiscountPolicy();

  it.each([
    [0],
    [100],
    [999999],
    [-50],
  ])("returns 0 for subtotal %i", (subtotal) => {
    expect(policy.computeDiscountCents(subtotal)).toBe(0);
  });
});

describe("PercentageDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([
      [-1, "percent must be between 0 and 100"],
      [101, "percent must be between 0 and 100"],
      [NaN, "percent must be between 0 and 100"],
      [Infinity, "percent must be between 0 and 100"],
    ])("rejects invalid percent %s", (percent, expectedMsg) => {
      expect(() => new PercentageDiscountPolicy(percent)).toThrow(RangeError);
      expect(() => new PercentageDiscountPolicy(percent)).toThrow(expectedMsg);
    });

    it("accepts boundary values 0 and 100", () => {
      expect(() => new PercentageDiscountPolicy(0)).not.toThrow();
      expect(() => new PercentageDiscountPolicy(100)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("computes 10% of 1000 = 100", () => {
      const policy = new PercentageDiscountPolicy(10);
      expect(policy.computeDiscountCents(1000)).toBe(100);
    });

    it("rounds down to nearest cent", () => {
      const policy = new PercentageDiscountPolicy(33);
      // 33% of 100 = 33, 33% of 101 = 33.33 → 33
      expect(policy.computeDiscountCents(101)).toBe(33);
    });

    it("returns 0 for zero subtotal", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(-100)).toBe(0);
    });

    it("100% discount equals subtotal", () => {
      const policy = new PercentageDiscountPolicy(100);
      expect(policy.computeDiscountCents(5000)).toBe(5000);
    });

    it("0% discount returns 0", () => {
      const policy = new PercentageDiscountPolicy(0);
      expect(policy.computeDiscountCents(5000)).toBe(0);
    });

    it("handles very large subtotal", () => {
      const policy = new PercentageDiscountPolicy(25);
      expect(policy.computeDiscountCents(1_000_000_00)).toBe(25_000_000);
    });
  });
});

describe("FixedAmountDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects negative amount", () => {
      expect(() => new FixedAmountDiscountPolicy(-1)).toThrow(RangeError);
    });

    it("rejects non-integer amount", () => {
      expect(() => new FixedAmountDiscountPolicy(10.5)).toThrow(RangeError);
    });

    it("accepts zero", () => {
      expect(() => new FixedAmountDiscountPolicy(0)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    const policy = new FixedAmountDiscountPolicy(500);

    it("returns amount when subtotal exceeds discount", () => {
      expect(policy.computeDiscountCents(1000)).toBe(500);
    });

    it("caps at subtotal when discount exceeds subtotal", () => {
      expect(policy.computeDiscountCents(200)).toBe(200);
    });

    it("returns 0 for zero subtotal", () => {
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      expect(policy.computeDiscountCents(-100)).toBe(0);
    });

    it("returns exact subtotal when equal", () => {
      expect(policy.computeDiscountCents(500)).toBe(500);
    });
  });
});

describe("CompositeDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects empty policies array", () => {
      expect(() => new CompositeDiscountPolicy([])).toThrow(
        "CompositeDiscountPolicy requires at least one policy",
      );
    });
  });

  describe("sum mode", () => {
    it("sums discounts from multiple policies on original subtotal", () => {
      const policies = [
        new PercentageDiscountPolicy(10), // 10% of 1000 = 100
        new FixedAmountDiscountPolicy(200), // fixed 200
      ];
      const composite = new CompositeDiscountPolicy(policies, "sum");
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("can exceed subtotal (clamping is done by Cart)", () => {
      const policies = [
        new PercentageDiscountPolicy(80), // 800
        new FixedAmountDiscountPolicy(500), // 500
      ];
      const composite = new CompositeDiscountPolicy(policies, "sum");
      // 800 + 500 = 1300, exceeds 1000 but sum mode doesn't clamp
      expect(composite.computeDiscountCents(1000)).toBe(1300);
    });

    it("returns 0 for zero subtotal", () => {
      const policies = [new PercentageDiscountPolicy(50)];
      const composite = new CompositeDiscountPolicy(policies, "sum");
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policies = [new FixedAmountDiscountPolicy(100)];
      const composite = new CompositeDiscountPolicy(policies, "sum");
      expect(composite.computeDiscountCents(-50)).toBe(0);
    });

    it("defaults to sum mode when not specified", () => {
      const policies = [
        new FixedAmountDiscountPolicy(100),
        new FixedAmountDiscountPolicy(200),
      ];
      const composite = new CompositeDiscountPolicy(policies);
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially on remaining subtotal", () => {
      const policies = [
        new PercentageDiscountPolicy(10), // 10% of 1000 = 100, remaining 900
        new PercentageDiscountPolicy(10), // 10% of 900 = 90
      ];
      const composite = new CompositeDiscountPolicy(policies, "chain");
      expect(composite.computeDiscountCents(1000)).toBe(190);
    });

    it("chain caps each step at remaining", () => {
      const policies = [
        new FixedAmountDiscountPolicy(800), // takes 800, remaining 200
        new FixedAmountDiscountPolicy(500), // takes min(500, 200) = 200
      ];
      const composite = new CompositeDiscountPolicy(policies, "chain");
      expect(composite.computeDiscountCents(1000)).toBe(1000);
    });

    it("ordering matters in chain mode", () => {
      const policies1 = [
        new PercentageDiscountPolicy(50), // 50% of 1000 = 500, remaining 500
        new FixedAmountDiscountPolicy(200), // 200 from 500
      ];
      const policies2 = [
        new FixedAmountDiscountPolicy(200), // 200, remaining 800
        new PercentageDiscountPolicy(50), // 50% of 800 = 400
      ];
      const composite1 = new CompositeDiscountPolicy(policies1, "chain");
      const composite2 = new CompositeDiscountPolicy(policies2, "chain");
      expect(composite1.computeDiscountCents(1000)).toBe(700);
      expect(composite2.computeDiscountCents(1000)).toBe(600);
    });

    it("returns 0 for zero subtotal", () => {
      const policies = [new PercentageDiscountPolicy(50)];
      const composite = new CompositeDiscountPolicy(policies, "chain");
      expect(composite.computeDiscountCents(0)).toBe(0);
    });
  });
});

import { describe, it, expect, vi } from "vitest";
import {
  NoTaxCalculator,
  RegionalTaxCalculator,
  AsyncTaxCalculator,
  totalLineWeightGrams,
  type AsyncTaxRateProvider,
} from "../src/tax.ts";
import type { CartLine } from "../src/product.ts";

describe("NoTaxCalculator", () => {
  const calc = new NoTaxCalculator();

  it("returns 0 for any input", () => {
    expect(calc.computeTaxCents(1000, "US")).toBe(0);
    expect(calc.computeTaxCents(0, "FR")).toBe(0);
    expect(calc.computeTaxCents(999999, "GB")).toBe(0);
  });
});

describe("RegionalTaxCalculator", () => {
  describe("constructor validation", () => {
    it("rejects negative default rate", () => {
      expect(() => new RegionalTaxCalculator({}, -0.01)).toThrow(RangeError);
    });

    it("rejects default rate above 1", () => {
      expect(() => new RegionalTaxCalculator({}, 1.01)).toThrow(RangeError);
    });

    it("rejects NaN default rate", () => {
      expect(() => new RegionalTaxCalculator({}, NaN)).toThrow(RangeError);
    });

    it("rejects invalid region rate", () => {
      expect(() => new RegionalTaxCalculator({ "US": 1.5 })).toThrow(RangeError);
    });

    it("rejects negative region rate", () => {
      expect(() => new RegionalTaxCalculator({ "US": -0.1 })).toThrow(RangeError);
    });

    it("accepts boundary rates 0 and 1", () => {
      expect(() => new RegionalTaxCalculator({ "US": 0, "FR": 1 }, 0)).not.toThrow();
      expect(() => new RegionalTaxCalculator({}, 1)).not.toThrow();
    });
  });

  describe("computeTaxCents", () => {
    const calc = new RegionalTaxCalculator(
      { "US": 0.08, "US-CA": 0.0875, "FR": 0.20 },
      0.05,
    );

    it("computes tax for known region", () => {
      // 8% of 1000 = 80
      expect(calc.computeTaxCents(1000, "US")).toBe(80);
    });

    it("uses sub-region rate when available", () => {
      // 8.75% of 1000 = 87.5 → 87
      expect(calc.computeTaxCents(1000, "US-CA")).toBe(87);
    });

    it("falls back to default rate for unknown region", () => {
      // 5% of 1000 = 50
      expect(calc.computeTaxCents(1000, "JP")).toBe(50);
    });

    it("rounds down to nearest cent", () => {
      // 20% of 999 = 199.8 → 199
      expect(calc.computeTaxCents(999, "FR")).toBe(199);
    });

    it("returns 0 for zero taxable amount", () => {
      expect(calc.computeTaxCents(0, "US")).toBe(0);
    });

    it("returns 0 for negative taxable amount", () => {
      expect(calc.computeTaxCents(-100, "US")).toBe(0);
    });

    it("works with zero default rate and unknown region", () => {
      const zeroDefault = new RegionalTaxCalculator({ "US": 0.1 });
      expect(zeroDefault.computeTaxCents(1000, "XX")).toBe(0);
    });
  });
});

describe("AsyncTaxCalculator", () => {
  it("computes tax from provider rate", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.10),
    };
