import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import { InventoryError, refreshPrices } from "../src/inventory.ts";
import type { PriceFetcher, InventoryChecker } from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";
import type { Product, CartLine } from "../src/product.ts";
import { PercentageDiscountPolicy } from "../src/pricing.ts";
import { FlatShippingCalculator } from "../src/shipping.ts";

const productA: Product = { id: "a", name: "Widget", unitPriceCents: 1000 };
const productB: Product = { id: "b", name: "Gadget", unitPriceCents: 2000 };

describe("refreshPrices", () => {
  it("updates line prices from fetcher", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn()
        .mockResolvedValueOnce(1100)
        .mockResolvedValueOnce(2200),
    };
    const lines: CartLine[] = [
      { product: productA, quantity: 2 },
      { product: productB, quantity: 1 },
    ];
    const result = await refreshPrices(lines, fetcher);
    expect(result[0].product.unitPriceCents).toBe(1100);
    expect(result[1].product.unitPriceCents).toBe(2200);
    expect(result[0].quantity).toBe(2);
  });

  it("throws RangeError for invalid fetched price", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(-1),
    };
    const lines: CartLine[] = [{ product: productA, quantity: 1 }];
    await expect(refreshPrices(lines, fetcher)).rejects.toThrow(RangeError);
  });

  it("throws RangeError for non-integer fetched price", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(10.5),
    };
    const lines: CartLine[] = [{ product: productA, quantity: 1 }];
    await expect(refreshPrices(lines, fetcher)).rejects.toThrow(RangeError);
  });

  it("propagates fetcher rejection", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("network")),
    };
    const lines: CartLine[] = [{ product: productA, quantity: 1 }];
    await expect(refreshPrices(lines, fetcher)).rejects.toThrow("network");
  });
});

describe("Cart.checkout()", () => {
  it("refreshes prices before computing totals", async () => {
    const cart = new Cart();
    cart.add(productA, 1);

    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(1500),
    };

    const result = await cart.checkout({ priceFetcher });
    expect(result.lines[0].product.unitPriceCents).toBe(1500);
    expect(result.totals.subtotalCents).toBe(1500);
  });

  it("works without any collaborators", async () => {
    const cart = new Cart();
    cart.add(productA, 2);
    const result = await cart.checkout();
    expect(result.totals.subtotalCents).toBe(2000);
  });

  it("throws InventoryError when item is unavailable", async () => {
    const cart = new Cart();
    cart.add(productA, 5);

    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: false, reason: "out of stock" }),
    };

    try {
      await cart.checkout({ inventoryChecker });
      expect.fail("should have thrown");
    } catch (e) {
      expect(e).toBeInstanceOf(InventoryError);
      const err = e as InventoryError;
      expect(err.productId).toBe("a");
      expect(err.requested).toBe(5);
      expect(err.message).toBe("out of stock");
    }
  });

  it("throws InventoryError on partial-stock denial", async () => {
    const cart = new Cart();
    cart.add(productA, 10);

    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 3,
      }),
    };

    try {
      await cart.checkout({ inventoryChecker });
      expect.fail("should have thrown");
    } catch (e) {
      expect(e).toBeInstanceOf(InventoryError);
      const err = e as InventoryError;
      expect(err.productId).toBe("a");
      expect(err.requested).toBe(10);
      expect(err.available).toBe(3);
    }
  });

  it("passes when inventory is available", async () => {
    const cart = new Cart();
    cart.add(productA, 2);

    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true }),
    };

    const result = await cart.checkout({ inventoryChecker });
    expect(result.totals.subtotalCents).toBe(2000);
  });

  it("uses asyncTaxProvider when supplied", async () => {
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.10),
    };
    const cart = new Cart({ region: "US-CA" });
    cart.add(productA, 1); // subtotal 1000, no discount → tax 10% of 1000 = 100

    const result = await cart.checkout({ asyncTaxProvider });
    expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US-CA");
    expect(result.totals.taxCents).toBe(100);
  });

  it("async tax uses discounted subtotal", async () => {
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.10),
    };
    const discountPolicy = new PercentageDiscountPolicy(20);
    const cart = new Cart({ discountPolicy, region: "US" });
    cart.add(productA, 1); // subtotal 1000, 20% discount = 200, taxable = 800

    const result = await cart.checkout({ asyncTaxProvider });
    expect(result.totals.discountCents).toBe(200);
    expect(result.totals.taxCents).toBe(80); // 10% of 800
  });

  it("combines price refresh, inventory, async tax, discount, and shipping", async () => {
    const discountPolicy = new PercentageDiscountPolicy(10);
    const shippingCalculator = new FlatShippingCalculator(500);
    const cart = new Cart({ discountPolicy, shippingCalculator, region: "US" });
    cart.add(productA, 2); // will be repriced

    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(1200),
    };
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 100 }),
    };
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.08),
    };

    const result = await cart.checkout({ priceFetcher, inventoryChecker, asyncTaxProvider });

    // subtotal: 1200 * 2 = 2400
    expect(result.totals.subtotalCents).toBe(2400);
    // discount: 10% of 2400 = 240
    expect(result.totals.discountCents).toBe(240);
    // taxable: 2400 - 240 = 2160, tax 8% = 172.8 → 172
    expect(result.totals.taxCents).toBe(172);
    // shipping: flat 500
    expect(result.totals.shippingCents).toBe(500);
    // total: 2160 + 172 + 500 = 2832
    expect(result.totals.totalCents).toBe(2832);
  });

  it("propagates asyncTaxProvider rejection", async () => {
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
    };
    const cart = new Cart();
    cart.add(productA, 1);
    await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow("tax service down");
  });

  it("first failing inventory item wins", async () => {
    const cart = new Cart();
    cart.add(productA, 1);
    cart.add(productB, 1);

    const inventoryChecker: InventoryChecker = {
      check: vi.fn()
        .mockResolvedValueOnce({ available: true })
        .mockResolvedValueOnce({ available: false, reason: "discontinued" }),
    };

    try {
      await cart.checkout({ inventoryChecker });
      expect.fail("should have thrown");
    } catch (e) {
      expect(e).toBeInstanceOf(InventoryError);
      expect((e as InventoryError).productId).toBe("b");
    }
  });
});

describe("InventoryError", () => {
